import type { FastifyInstance } from 'fastify';
import { ApiError } from './errors.js';

/** 전역 에러 핸들러 및 404 핸들러를 등록한다. 라우트보다 먼저 호출한다. */
export function registerErrorHandling(app: FastifyInstance): void {
  app.setErrorHandler((err, _req, reply) => {
    if (err instanceof ApiError) {
      return reply.code(err.statusCode).send({ errors: err.errors });
    }
    // 잘못된 JSON 바디 등 Fastify 자체 400은 계약상 422로 매핑한다.
    if ((err as { statusCode?: number }).statusCode === 400) {
      return reply.code(422).send({ errors: { body: ["is invalid"] } });
    }
    app.log.error(err);
    return reply.code(500).send({ errors: { server: ["internal error"] } });
  });

  app.setNotFoundHandler((_req, reply) => {
    return reply.code(404).send({ errors: { route: ["not found"] } });
  });
}

