import jwt from 'jsonwebtoken';

const SECRET = process.env.JWT_SECRET ?? 'realworld-dev-secret';

/** 사용자 id를 담은 JWT를 발급한다. */
export function signToken(userId: number): string {
  // jti를 넣어 같은 초에 재발급해도 토큰 문자열이 달라지게 한다.
  return jwt.sign({ id: userId, jti: `${Date.now()}-${Math.random()}` }, SECRET, {
    expiresIn: '30d',
  });
}

/** 토큰을 검증해 사용자 id를 돌려준다. 무효하면 null. */
export function verifyToken(token: string): number | null {
  try {
    const payload = jwt.verify(token, SECRET) as { id?: unknown };
    return typeof payload.id === 'number' ? payload.id : null;
  } catch {
    return null;
  }
}

