import type { FastifyRequest } from 'fastify';
import { ApiError } from '../errors.js';
import { verifyToken } from './jwt.js';

declare module 'fastify' {
  interface FastifyRequest {
    /** 인증된 사용자 id. optional-auth 라우트에서는 null일 수 있다. */
    userId: number | null;
  }
}

/** `Authorization: Token <jwt>` 헤더에서 사용자 id를 추출한다. */
function extractUserId(req: FastifyRequest): number | null {
  const header = req.headers.authorization;
  if (!header) return null;
  const [scheme, token] = header.split(' ');
  if (scheme !== 'Token' || !token) return null;
  return verifyToken(token);
}

/** 인증 필수 라우트용 preHandler. 실패 시 401을 던진다. */
export async function requireAuth(req: FastifyRequest): Promise<void> {
  const userId = extractUserId(req);
  if (userId === null) throw ApiError.tokenMissing();
  req.userId = userId;
}

/** 선택 인증 라우트용 preHandler. 실패해도 익명으로 통과시킨다. */
export async function optionalAuth(req: FastifyRequest): Promise<void> {
  req.userId = extractUserId(req);
}

