import { ApiError } from './errors.js';

/** 요청 바디에서 래퍼 키(`user`/`article`/`comment`) 안쪽 객체를 꺼낸다. */
export function unwrap(body: unknown, key: string): Record<string, unknown> {
  if (typeof body !== 'object' || body === null) throw ApiError.blank(key);
  const inner = (body as Record<string, unknown>)[key];
  if (typeof inner !== 'object' || inner === null || Array.isArray(inner)) {
    throw ApiError.blank(key);
  }
  return inner as Record<string, unknown>;
}

/** 값이 존재하는 비어 있지 않은 문자열인지 확인한다. 아니면 422. */
export function requireString(obj: Record<string, unknown>, field: string): string {
  const value = obj[field];
  if (typeof value !== 'string' || value.trim() === '') throw ApiError.blank(field);
  return value;
}

/**
 * 선택 필드지만 값이 오면 비어 있으면 안 되는 문자열.
 * 키가 없으면 undefined를 돌려준다.
 */
export function optionalRequiredString(
  obj: Record<string, unknown>,
  field: string,
): string | undefined {
  if (!Object.hasOwn(obj, field)) return undefined;
  return requireString(obj, field);
}

/**
 * nullable 문자열 필드(bio/image). 키가 없으면 undefined,
 * `null`이나 빈 문자열이면 null로 정규화한다.
 */
export function nullableString(
  obj: Record<string, unknown>,
  field: string,
): string | null | undefined {
  if (!Object.hasOwn(obj, field)) return undefined;
  const value = obj[field];
  if (value === null) return null;
  if (typeof value !== 'string') throw ApiError.blank(field);
  return value === '' ? null : value;
}

/** NIST SP 800-63B: 최소 8자, 64자 이상 허용, 조합 규칙 없음. */
export function validatePassword(password: string): void {
  if (password.length < 8) {
    throw ApiError.unprocessable({
      password: ['is too short (minimum is 8 characters)'],
    });
  }
}

/** `tagList`를 파싱한다. 키 없음 → undefined, null → 422, 배열 → 문자열 목록. */
export function parseTagList(obj: Record<string, unknown>): string[] | undefined {
  if (!Object.hasOwn(obj, 'tagList')) return undefined;
  const value = obj.tagList;
  if (!Array.isArray(value) || value.some((t) => typeof t !== 'string')) {
    throw ApiError.unprocessable({ tagList: ['is invalid'] });
  }
  return value as string[];
}

/** 쿼리 파라미터를 양의 정수로 파싱한다. 없거나 무효하면 기본값. */
export function parseIntParam(value: unknown, fallback: number): number {
  if (typeof value !== 'string') return fallback;
  const n = Number.parseInt(value, 10);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

