import type { FastifyPluginAsync } from 'fastify';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { signToken } from '../auth/jwt.js';
import { hashPassword, verifyPassword } from '../auth/password.js';
import { toUserResponse } from '../serializers/index.js';
import { requireString, unwrap, validatePassword } from '../validation.js';

export const usersRoutes: FastifyPluginAsync = async (app) => {
  // 회원가입
  app.post('/users', async (req, reply) => {
    const input = unwrap(req.body, 'user');
    const username = requireString(input, 'username');
    const email = requireString(input, 'email');
    const password = requireString(input, 'password');
    validatePassword(password);

    // 유니크 충돌은 username → email 순으로 검사해 409로 매핑한다.
    if (await prisma.user.findUnique({ where: { username } })) {
      throw ApiError.conflict('username');
    }
    if (await prisma.user.findUnique({ where: { email } })) {
      throw ApiError.conflict('email');
    }

    const user = await prisma.user.create({
      data: { username, email, passwordHash: await hashPassword(password) },
    });
    return reply.code(201).send(toUserResponse(user, signToken(user.id)));
  });

  // 로그인
  app.post('/users/login', async (req) => {
    const input = unwrap(req.body, 'user');
    const email = requireString(input, 'email');
    const password = requireString(input, 'password');

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await verifyPassword(password, user.passwordHash))) {
      throw ApiError.invalidCredentials();
    }
    return toUserResponse(user, signToken(user.id));
  });
};

