import type { FastifyPluginAsync } from 'fastify';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { requireAuth } from '../auth/hooks.js';
import { signToken } from '../auth/jwt.js';
import { hashPassword } from '../auth/password.js';
import { toUserResponse } from '../serializers/index.js';
import {
  nullableString,
  optionalRequiredString,
  unwrap,
  validatePassword,
} from '../validation.js';

export const userRoutes: FastifyPluginAsync = async (app) => {
  // 현재 사용자 조회
  app.get('/user', { preHandler: requireAuth }, async (req) => {
    const user = await prisma.user.findUnique({ where: { id: req.userId! } });
    if (!user) throw ApiError.tokenMissing();
    return toUserResponse(user, signToken(user.id));
  });

  // 현재 사용자 수정
  app.put('/user', { preHandler: requireAuth }, async (req) => {
    const input = unwrap(req.body, 'user');
    // username/email/password는 빈 값·null을 거부, bio/image는 null로 정규화.
    const username = optionalRequiredString(input, 'username');
    const email = optionalRequiredString(input, 'email');
    const password = optionalRequiredString(input, 'password');
    const bio = nullableString(input, 'bio');
    const image = nullableString(input, 'image');
    if (password !== undefined) validatePassword(password);

    const userId = req.userId!;
    if (username !== undefined) {
      const owner = await prisma.user.findUnique({ where: { username } });
      if (owner && owner.id !== userId) throw ApiError.conflict('username');
    }
    if (email !== undefined) {
      const owner = await prisma.user.findUnique({ where: { email } });
      if (owner && owner.id !== userId) throw ApiError.conflict('email');
    }

    const user = await prisma.user.update({
      where: { id: userId },
      data: {
        ...(username !== undefined && { username }),
        ...(email !== undefined && { email }),
        ...(password !== undefined && { passwordHash: await hashPassword(password) }),
        ...(bio !== undefined && { bio }),
        ...(image !== undefined && { image }),
      },
    });
    // username/email이 바뀌면 새 토큰을 발급한다.
    return toUserResponse(user, signToken(user.id));
  });
};

