import { randomBytes } from 'node:crypto';

/**
 * 제목을 URL 친화적인 slug로 바꾸고 짧은 랜덤 접미사를 붙인다.
 * 동일 제목의 글이 여러 건이어도 slug가 충돌하지 않는다.
 */
export function makeSlug(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
  return `${base || 'article'}-${randomBytes(4).toString('hex')}`;
}

