import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import type { ArticleWithRelations } from '../serializers/index.js';
import type { ViewerId } from '../types.js';

/** 존재하지 않는 id — 익명 뷰어일 때 관계 조회를 빈 배열로 만들기 위한 값. */
const NO_USER = -1;

/** viewer 기준으로 favorited/following 계산에 필요한 관계를 include한다. */
export function articleInclude(viewerId: ViewerId) {
  const uid = viewerId ?? NO_USER;
  return {
    author: { include: { followers: { where: { followerId: uid } } } },
    tags: { include: { tag: true } },
    favorites: { where: { userId: uid } },
    _count: { select: { favorites: true } },
  } as const;
}

type RawArticle = {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { username: string; bio: string | null; image: string | null; followers: unknown[] };
  tags: { order: number; tag: { name: string } }[];
  _count: { favorites: number };
  favorites: unknown[];
};

/** Prisma 결과를 시리얼라이저가 요구하는 형태로 옮긴다. */
export function withViewerRelations(a: RawArticle): ArticleWithRelations {
  return { ...a, authorFollowedBy: a.author.followers };
}

/** slug로 글을 로드한다. 없으면 404. */
export async function loadArticleOr404(
  slug: string,
  viewerId: ViewerId,
): Promise<ArticleWithRelations & { id: number; authorId: number }> {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: articleInclude(viewerId),
  });
  if (!article) throw ApiError.notFound('article');
  return { ...withViewerRelations(article), id: article.id, authorId: article.authorId };
}

/** 태그 이름 목록을 Tag 레코드로 확보하고 글에 순서대로 연결한다. */
export async function setArticleTags(articleId: number, tagList: string[]): Promise<void> {
  await prisma.articleTag.deleteMany({ where: { articleId } });
  // 중복 태그는 조인 테이블 PK가 (articleId, tagId)이므로 첫 등장만 남긴다.
  const unique = [...new Set(tagList.filter((name) => name.trim() !== ''))];
  for (const [order, name] of unique.entries()) {
    const tag = await prisma.tag.upsert({
      where: { name },
      create: { name },
      update: {},
    });
    await prisma.articleTag.create({ data: { articleId, tagId: tag.id, order } });
  }
}

