import type { FastifyPluginAsync } from 'fastify';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { optionalAuth, requireAuth } from '../auth/hooks.js';
import { toArticleResponse, toArticlesResponse } from '../serializers/index.js';
import {
  articleInclude,
  loadArticleOr404,
  setArticleTags,
  withViewerRelations,
} from '../services/articles.js';
import { makeSlug } from '../services/slug.js';
import {
  optionalRequiredString,
  parseIntParam,
  parseTagList,
  requireString,
  unwrap,
} from '../validation.js';

type SlugParams = { slug: string };
type ListQuery = {
  tag?: string;
  author?: string;
  favorited?: string;
  limit?: string;
  offset?: string;
};

// 목록·피드 공통 정렬: 최신 우선, 동시각이면 id 내림차순으로 안정화.
const LIST_ORDER = [{ createdAt: 'desc' as const }, { id: 'desc' as const }];

export const articlesRoutes: FastifyPluginAsync = async (app) => {
  // 피드 — `/articles/:slug`보다 먼저 등록한다.
  app.get<{ Querystring: ListQuery }>(
    '/articles/feed',
    { preHandler: requireAuth },
    async (req) => {
      const viewerId = req.userId!;
      const limit = parseIntParam(req.query.limit, 20);
      const offset = parseIntParam(req.query.offset, 0);
      const where = { author: { followers: { some: { followerId: viewerId } } } };

      const [items, count] = await Promise.all([
        prisma.article.findMany({
          where,
          include: articleInclude(viewerId),
          orderBy: LIST_ORDER,
          skip: offset,
          take: limit,
        }),
        prisma.article.count({ where }),
      ]);
      return toArticlesResponse(items.map(withViewerRelations), count);
    },
  );

  // 글 목록 (tag/author/favorited 필터는 AND 결합)
  app.get<{ Querystring: ListQuery }>('/articles', { preHandler: optionalAuth }, async (req) => {
    const { tag, author, favorited } = req.query;
    const limit = parseIntParam(req.query.limit, 20);
    const offset = parseIntParam(req.query.offset, 0);
    const where = {
      ...(tag && { tags: { some: { tag: { name: tag } } } }),
      ...(author && { author: { username: author } }),
      ...(favorited && { favorites: { some: { user: { username: favorited } } } }),
    };

    const [items, count] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(req.userId),
        orderBy: LIST_ORDER,
        skip: offset,
        take: limit,
      }),
      // articlesCount는 페이지네이션 전 전체 개수다.
      prisma.article.count({ where }),
    ]);
    return toArticlesResponse(items.map(withViewerRelations), count);
  });

  // 단건 조회
  app.get<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: optionalAuth },
    async (req) => toArticleResponse(await loadArticleOr404(req.params.slug, req.userId)),
  );

  // 글 작성
  app.post('/articles', { preHandler: requireAuth }, async (req, reply) => {
    const input = unwrap(req.body, 'article');
    const title = requireString(input, 'title');
    const description = requireString(input, 'description');
    const body = requireString(input, 'body');
    const tagList = parseTagList(input);

    const created = await prisma.article.create({
      data: { slug: makeSlug(title), title, description, body, authorId: req.userId! },
    });
    if (tagList && tagList.length > 0) await setArticleTags(created.id, tagList);

    return reply
      .code(201)
      .send(toArticleResponse(await loadArticleOr404(created.slug, req.userId)));
  });

  // 글 수정 — slug는 유지한다.
  app.put<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req) => {
      const input = unwrap(req.body, 'article');
      const title = optionalRequiredString(input, 'title');
      const description = optionalRequiredString(input, 'description');
      const body = optionalRequiredString(input, 'body');
      const tagList = parseTagList(input);

      // 존재 검사가 소유권 검사보다 앞선다.
      const article = await loadArticleOr404(req.params.slug, req.userId);
      if (article.authorId !== req.userId) throw ApiError.forbidden('article');

      await prisma.article.update({
        where: { id: article.id },
        data: {
          ...(title !== undefined && { title }),
          ...(description !== undefined && { description }),
          ...(body !== undefined && { body }),
          // 태그만 바뀌어도 updatedAt이 갱신되도록 명시한다.
          updatedAt: new Date(),
        },
      });
      if (tagList !== undefined) await setArticleTags(article.id, tagList);

      return toArticleResponse(await loadArticleOr404(req.params.slug, req.userId));
    },
  );

  // 글 삭제
  app.delete<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (req, reply) => {
      const article = await loadArticleOr404(req.params.slug, req.userId);
      if (article.authorId !== req.userId) throw ApiError.forbidden('article');
      await prisma.article.delete({ where: { id: article.id } });
      return reply.code(204).send();
    },
  );
};

