import type { FastifyPluginAsync } from 'fastify';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { optionalAuth, requireAuth } from '../auth/hooks.js';
import {
  toCommentResponse,
  toCommentsResponse,
  type CommentWithRelations,
} from '../serializers/index.js';
import { loadArticleOr404 } from '../services/articles.js';
import { requireString, unwrap } from '../validation.js';
import type { ViewerId } from '../types.js';

type SlugParams = { slug: string };
type CommentParams = { slug: string; id: string };

const NO_USER = -1;

function commentInclude(viewerId: ViewerId) {
  return {
    author: { include: { followers: { where: { followerId: viewerId ?? NO_USER } } } },
  } as const;
}

type RawComment = {
  id: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { username: string; bio: string | null; image: string | null; followers: unknown[] };
};

function withViewerRelations(c: RawComment): CommentWithRelations {
  return { ...c, authorFollowedBy: c.author.followers };
}

export const commentsRoutes: FastifyPluginAsync = async (app) => {
  // 댓글 작성
  app.post<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: requireAuth },
    async (req, reply) => {
      const input = unwrap(req.body, 'comment');
      const body = requireString(input, 'body');
      const article = await loadArticleOr404(req.params.slug, req.userId);

      const created = await prisma.comment.create({
        data: { body, articleId: article.id, authorId: req.userId! },
        include: commentInclude(req.userId),
      });
      return reply.code(201).send(toCommentResponse(withViewerRelations(created)));
    },
  );

  // 댓글 목록
  app.get<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (req) => {
      const article = await loadArticleOr404(req.params.slug, req.userId);
      const comments = await prisma.comment.findMany({
        where: { articleId: article.id },
        include: commentInclude(req.userId),
        orderBy: { id: 'asc' },
      });
      return toCommentsResponse(comments.map(withViewerRelations));
    },
  );

  // 댓글 삭제 — 존재 검사 후 소유권 검사.
  app.delete<{ Params: CommentParams }>(
    '/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (req, reply) => {
      const article = await loadArticleOr404(req.params.slug, req.userId);
      const id = Number.parseInt(req.params.id, 10);
      if (!Number.isFinite(id)) throw ApiError.notFound('comment');

      const comment = await prisma.comment.findFirst({
        where: { id, articleId: article.id },
      });
      if (!comment) throw ApiError.notFound('comment');
      if (comment.authorId !== req.userId) throw ApiError.forbidden('comment');

      await prisma.comment.delete({ where: { id } });
      return reply.code(204).send();
    },
  );
};

