import Fastify, { type FastifyInstance, type FastifyServerOptions } from 'fastify';
import { registerErrorHandling } from './error-handler.js';
import { usersRoutes } from './routes/users.js';
import { userRoutes } from './routes/user.js';
import { profilesRoutes } from './routes/profiles.js';
import { articlesRoutes } from './routes/articles.js';
import { favoritesRoutes } from './routes/favorites.js';
import { commentsRoutes } from './routes/comments.js';
import { tagsRoutes } from './routes/tags.js';

/** Fastify 인스턴스를 조립한다. listen은 하지 않는다(테스트에서 inject 사용). */
export function buildApp(opts: FastifyServerOptions = {}): FastifyInstance {
  const app = Fastify({ logger: false, ...opts });

  // 1. 에러 핸들러를 라우트보다 먼저 등록한다.
  registerErrorHandling(app);

  // 2. 인증 훅이 채우는 필드를 데코레이트한다.
  app.decorateRequest('userId', null);

  // 3. 라우트 플러그인 — 전부 `/api` 프리픽스.
  app.register(usersRoutes, { prefix: '/api' });
  app.register(userRoutes, { prefix: '/api' });
  app.register(profilesRoutes, { prefix: '/api' });
  app.register(articlesRoutes, { prefix: '/api' });
  app.register(favoritesRoutes, { prefix: '/api' });
  app.register(commentsRoutes, { prefix: '/api' });
  app.register(tagsRoutes, { prefix: '/api' });

  return app;
}

